import{_ as p,W as o,s as r,u as d,I as s,ah as l,w as a,Z as t,A as i}from"./chunks/framework.Dx7wo2et.js";import"./chunks/theme.CjgFg8Ql.js";const C=JSON.parse('{"title":"如何将 Silverblue 重定位到 Fedora Linux 39 | LCTT x X-CMD","titleTemplate":false,"description":"如何将 Silverblue 重定位到 Fedora Linux 39 | LCTT (202311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何将 Silverblue 重定位到 Fedora Linux 39 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何将 Silverblue 重定位到 Fedora Linux 39 | LCTT (202311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202311/20231108 How to rebase to Fedora Linux 39 on Silverblue","title":"如何将 Silverblue 重定位到 Fedora Linux 39","tag":"202311"},"relativePath":"202311/20231108 How to rebase to Fedora Linux 39 on Silverblue.md","filePath":"[post].md"}'),u={name:"202311/20231108 How to rebase to Fedora Linux 39 on Silverblue.md"};function b(g,e,v,m,h,f){const n=o("Link");return d(),r("div",null,[e[28]||(e[28]=s("h1",{id:"如何将-silverblue-重定位到-fedora-linux-39",tabindex:"-1"},[a("如何将 Silverblue 重定位到 Fedora Linux 39 "),s("a",{class:"header-anchor",href:"#如何将-silverblue-重定位到-fedora-linux-39","aria-label":"Permalink to 如何将 Silverblue 重定位到 Fedora Linux 39"},"​")],-1)),e[29]||(e[29]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202311/11/152119r6nv12c115vntzp4.png",alt:""})],-1)),s("p",null,[e[2]||(e[2]=a("Fedora Silverblue 是 ")),t(n,{href:"https://docs.fedoraproject.org/en-US/fedora-silverblue/"},{default:i(()=>e[0]||(e[0]=[a("一款基于 Fedora Linux 构建的面向桌面的操作系统")])),_:1}),e[3]||(e[3]=a("。这款操作系统非常适合日常使用、开发和容器化的工作流程。它有 ")),t(n,{href:"https://fedoramagazine.org/give-fedora-silverblue-a-test-drive/"},{default:i(()=>e[1]||(e[1]=[a("许多优势")])),_:1}),e[4]||(e[4]=a("，例如可以在发生问题时轻松回滚操作。如果你想在 Fedora Silverblue 系统上更新或将系统 ")),e[5]||(e[5]=s("ruby",null,[a("重定位"),s("rt",null,"rebase")],-1)),e[6]||(e[6]=a(" 到 Fedora Linux 39，本文会提供帮助。文章不仅会指导你执行操作，还会教你如何在遇到意外情况时撤销操作。"))]),e[30]||(e[30]=l(`<h3 id="更新你目前的系统" tabindex="-1">更新你目前的系统 <a class="header-anchor" href="#更新你目前的系统" aria-label="Permalink to 更新你目前的系统">​</a></h3><p>在实际重定位至 Fedora Linux 39 前，你需要先安装所有待处理的更新。你可以在终端中使用下面的命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ rpm-ostree update</span></span></code></pre></div><p>或者你也可以通过 GNOME “软件”应用安装更新，然后重新启动系统。</p><h3 id="使用-gnome-软件-重定位" tabindex="-1">使用 GNOME “软件” 重定位 <a class="header-anchor" href="#使用-gnome-软件-重定位" aria-label="Permalink to 使用 GNOME “软件” 重定位">​</a></h3><p>在 GNOME “软件”应用的更新页面上，你可以看到 Fedora Linux 的新版本已经可以使用。</p><p>首先，你需要点击 “<ruby>下载<rt>Download</rt></ruby>” 按钮来下载新的操作系统镜像。这个过程可能需要一些时间。完成后，你会发现更新已经准备好进行安装。</p><p>接下来，点击 “<ruby>重新启动 &amp; 升级<rt>Restart &amp; Upgrade</rt></ruby>” 按钮。这个过程只需要几分钟，一旦更新完成，计算机将会重新启动。重启后，你会看到崭新的 Fedora Linux 39 的系统环境，看起来很简单，是吧？</p><h3 id="使用终端进行重定位" tabindex="-1">使用终端进行重定位 <a class="header-anchor" href="#使用终端进行重定位" aria-label="Permalink to 使用终端进行重定位">​</a></h3><p>如果你更喜欢在终端操作，那么这部分指南就是为你准备的。</p><p>首先你需要确认 39 版本是否已经可以使用：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ostree remote refs fedora</span></span></code></pre></div><p>在命令输出中你应该看到如下内容：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fedora:fedora/39/x86_64/silverblue</span></span></code></pre></div><p>如果你想保留当前的部署（这意味着这个部署将会持续在 GRUB 中显示为一个选项，直到你手动移除它），你可以通过运行下面的命令实现：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 0 是在 rpm-ostree 状态中的条目位置</span></span>
<span class="line"><span>$ sudo ostree admin pin 0</span></span></code></pre></div><p>如果你想移除已经固定的部署，你可以使用下面的命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 2 是在 rpm-ostree 状态中的条目位置</span></span>
<span class="line"><span>$ sudo ostree admin pin --unpin 2</span></span></code></pre></div><p>然后，将你的系统重定位至 Fedora Linux 39 镜像。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ rpm-ostree rebase fedora:fedora/39/x86_64/silverblue</span></span></code></pre></div><p>最后，重启你的电脑，启动进入 Fedora Linux 39 版本。</p><h3 id="如何进行回滚" tabindex="-1">如何进行回滚 <a class="header-anchor" href="#如何进行回滚" aria-label="Permalink to 如何进行回滚">​</a></h3><p>如果遇到任何问题（例如，如果你无法启动 Fedora Linux 39），回滚是非常容易的。在系统启动时，在 GRUB 菜单中选择 Fedora Linux 39 之前的版本，然后你的系统就会启动这个更早的版本而非 Fedora Linux 39。如果你在启动过程中看不到 GRUB 菜单，那么在启动时尝试按下 <code>ESC</code> 键。如果你想让更早版本的选择永久生效，你可以使用下面的命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ rpm-ostree rollback</span></span></code></pre></div><p>现在，你已经了解如何将 Fedora Silverblue 系统重定位到 Fedora Linux 39，以及如何进行系统回滚了。那么何不今天就试试看呢？</p><h3 id="常见问题解答" tabindex="-1">常见问题解答 <a class="header-anchor" href="#常见问题解答" aria-label="Permalink to 常见问题解答">​</a></h3><p>在每篇关于重定位 Silverblue 到新版本的文章的评论中，总会有相似的问题，因此我会在这个部分尝试解答这些问题。</p><p><strong>问题：在 Fedora 的重定位过程中我能跳过某些版本吗？例如直接从 Fedora 37 Silverblue 更新到 Fedora 39 Silverblue。</strong></p><p>答案：虽然有时可能可以在重定位过程中跳过某些版本，但并不推荐这样操作。你应当始终更新到紧邻的新版本（例如从 38 更新到 39），以避免不必要的错误。</p>`,29)),s("p",null,[s("strong",null,[e[8]||(e[8]=a("问题：我安装了 ")),t(n,{href:"https://rpmfusion.org/"},{default:i(()=>e[7]||(e[7]=[a("rpm-fusion")])),_:1}),e[9]||(e[9]=a(" ，在重定位过程中出现错误，我应当怎样进行重定位？"))])]),s("p",null,[e[11]||(e[11]=a("答案：如果你在 Silverblue 安装上加入了 ")),t(n,{href:"https://rpmfusion.org/"},{default:i(()=>e[10]||(e[10]=[a("rpm-fusion")])),_:1}),e[12]||(e[12]=a("，你在重定位前应当执行以下操作："))]),e[31]||(e[31]=l(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rpm-ostree update \\</span></span>
<span class="line"><span>    --uninstall rpmfusion-free-release \\</span></span>
<span class="line"><span>    --uninstall rpmfusion-nonfree-release \\</span></span>
<span class="line"><span>    --install rpmfusion-free-release \\</span></span>
<span class="line"><span>    --install rpmfusion-nonfree-release</span></span></code></pre></div><p>执行完上述操作后，你可以按照本篇博文的步骤完成重定位过程。</p><p><strong>问题：这个指南是否适用于其他的 ostree 版本（例如 Kinoite， Sericea）？</strong></p><p>答案：是的，你可以照着本指南的 <em>使用终端进行重定位</em> 部分的操作来完成所有的 Fedora ostree 版本的重定位过程。只需要使用对应的分支即可。例如对于 Kinoite，你可以使用</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fedora:fedora/39/x86_64/kinoite</span></span></code></pre></div><p>而非</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fedora:fedora/39/x86_64/silverblue</span></span></code></pre></div><p><em>（题图：MJ/71150afc-ae44-48f3-8689-e86758e07b1e）</em></p><hr>`,9)),s("p",null,[e[14]||(e[14]=a("via: ")),t(n,{href:"https://fedoramagazine.org/how-to-rebase-to-fedora-linux-39-on-silverblue/"},{default:i(()=>e[13]||(e[13]=[a("https://fedoramagazine.org/how-to-rebase-to-fedora-linux-39-on-silverblue/")])),_:1})]),s("p",null,[e[19]||(e[19]=a("作者：")),t(n,{href:"https://fedoramagazine.org/author/zlopez/"},{default:i(()=>e[15]||(e[15]=[a("Michal Konečný")])),_:1}),e[20]||(e[20]=a(" 选题：")),t(n,{href:"https://github.com/lujun9972"},{default:i(()=>e[16]||(e[16]=[a("lujun9972")])),_:1}),e[21]||(e[21]=a(" 译者：")),t(n,{href:"https://linux.cn/lctt/ChatGPT"},{default:i(()=>e[17]||(e[17]=[a("ChatGPT")])),_:1}),e[22]||(e[22]=a(" 校对：")),t(n,{href:"https://github.com/wxy"},{default:i(()=>e[18]||(e[18]=[a("wxy")])),_:1})]),s("p",null,[e[25]||(e[25]=a("本文由 ")),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>e[23]||(e[23]=[a("LCTT")])),_:1}),e[26]||(e[26]=a(" 原创编译，")),t(n,{href:"https://linux.cn/"},{default:i(()=>e[24]||(e[24]=[a("Linux中国")])),_:1}),e[27]||(e[27]=a(" 荣誉推出"))])])}c